cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');

// Search for flight FLD3D594
const flight = db.prepare(\"SELECT * FROM flights WHERE flight_id = ? AND source_skill = 'tau2Airline'\").get('FLD3D594');
if (flight) {
  console.log('=== FLIGHT FLD3D594 ===');
  console.log('Origin:', flight.origin);
  console.log('Destination:', flight.destination);
  console.log('Departure:', flight.departure_time);
  console.log('Arrival:', flight.arrival_time);
  const dates = JSON.parse(flight.dates_json || '{}');
  console.log('Dates:', JSON.stringify(dates, null, 2));
} else {
  console.log('Flight FLD3D594 not found');
  // Search broadly
  const all = db.prepare(\"SELECT flight_id, origin, destination FROM flights WHERE source_skill='tau2Airline' AND origin='LAX' AND destination='SFO'\").all();
  console.log('LAX->SFO flights:', all);
}
"

