const db = require('better-sqlite3')('world.db');
const user = db.prepare(\"SELECT * FROM users WHERE user_id = 'user_fa209a3f'\").get();
if (user) {
  console.log('User ID:', user.user_id);
  console.log('Name:', user.name);
  console.log('Membership:', user.loyalty_tier);
  console.log('Payment Methods:', JSON.stringify(JSON.parse(user.payment_methods_json || '{}'), null, 2));

  // Check reservations
  const reservations = db.prepare(\"SELECT * FROM flight_bookings WHERE user_id = 'user_fa209a3f' AND source_skill = 'tau2Airline'\").all();
  console.log('Reservations count:', reservations.length);
  reservations.forEach(r => {
    console.log('  Reservation:', r.booking_id, '| Status:', r.status, '| Flights:', r.flights_json);
  });
} else {
  console.log('User not found');
}
"

